-- v4.3.3 Graph Runtime assurance and Definition supply-chain evidence.
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_ASSURANCE_EVIDENCE (EVIDENCE_ID VARCHAR2(128) PRIMARY KEY, RUN_ID VARCHAR2(128), EVIDENCE_TYPE VARCHAR2(64) NOT NULL, STATUS VARCHAR2(32) NOT NULL, ACTOR_ID VARCHAR2(256), DETAIL_JSON CLOB DEFAULT ''{}'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_ASSURANCE_RUN FOREIGN KEY(RUN_ID) REFERENCES GRAPH_RUNS(RUN_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_DEFINITION_PROVENANCE (PROVENANCE_ID VARCHAR2(128) PRIMARY KEY, GRAPH_VERSION_ID VARCHAR2(128) NOT NULL, PARENT_DIGEST VARCHAR2(64), PUBLISHER_ID VARCHAR2(256), SOURCE_URI VARCHAR2(1024), FORMAT_VERSION VARCHAR2(32) NOT NULL, COMPILER_VERSION VARCHAR2(64), DOCUMENT_DIGEST VARCHAR2(64) NOT NULL, TRUST_STATE VARCHAR2(32) DEFAULT ''UNTRUSTED_DRAFT'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_PROVENANCE_VERSION FOREIGN KEY(GRAPH_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID), CONSTRAINT UK_GRAPH_PROVENANCE_VERSION UNIQUE(GRAPH_VERSION_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_DEFINITION_DEPENDENCIES (DEPENDENCY_ID VARCHAR2(128) PRIMARY KEY, GRAPH_VERSION_ID VARCHAR2(128) NOT NULL, DEPENDENCY_KIND VARCHAR2(32) NOT NULL, DEPENDENCY_NAME VARCHAR2(256) NOT NULL, DEPENDENCY_VERSION VARCHAR2(128) NOT NULL, DEPENDENCY_DIGEST VARCHAR2(64), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_DEPENDENCY_VERSION FOREIGN KEY(GRAPH_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID), CONSTRAINT UK_GRAPH_DEPENDENCY UNIQUE(GRAPH_VERSION_ID,DEPENDENCY_KIND,DEPENDENCY_NAME,DEPENDENCY_VERSION,DEPENDENCY_DIGEST))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_DEFINITION_SIGNATURES (SIGNATURE_ID VARCHAR2(128) PRIMARY KEY, GRAPH_VERSION_ID VARCHAR2(128) NOT NULL, ALGORITHM VARCHAR2(32) NOT NULL, KEY_ID VARCHAR2(256) NOT NULL, SIGNATURE_VALUE CLOB NOT NULL, STATUS VARCHAR2(32) DEFAULT ''UNVERIFIED'' NOT NULL, VERIFIED_AT TIMESTAMP, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_SIGNATURE_VERSION FOREIGN KEY(GRAPH_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID), CONSTRAINT UK_GRAPH_SIGNATURE UNIQUE(GRAPH_VERSION_ID,KEY_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_DEFINITION_SCANS (SCAN_ID VARCHAR2(128) PRIMARY KEY, GRAPH_VERSION_ID VARCHAR2(128) NOT NULL, SCAN_VERSION VARCHAR2(32) NOT NULL, FINDINGS_JSON CLOB DEFAULT ''[]'' NOT NULL, RISK_LEVEL VARCHAR2(16) DEFAULT ''LOW'' NOT NULL, STATUS VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_SCAN_VERSION FOREIGN KEY(GRAPH_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_DYNAMIC_PROPOSALS (PROPOSAL_ID VARCHAR2(128) PRIMARY KEY, SOURCE_VERSION_ID VARCHAR2(128) NOT NULL, TARGET_VERSION_ID VARCHAR2(128), RUN_ID VARCHAR2(128), CHECKPOINT_ID VARCHAR2(128), OPERATIONS_JSON CLOB NOT NULL, STATE_MAPPING_JSON CLOB DEFAULT ''{}'' NOT NULL, RISK_JSON CLOB DEFAULT ''{}'' NOT NULL, STATUS VARCHAR2(32) DEFAULT ''DRAFT'' NOT NULL, APPROVAL_ID VARCHAR2(128), EXPECTED_VERSION VARCHAR2(128), ACTOR_ID VARCHAR2(256) NOT NULL, REASON VARCHAR2(2000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_DYNAMIC_SOURCE FOREIGN KEY(SOURCE_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID), CONSTRAINT FK_GRAPH_DYNAMIC_TARGET FOREIGN KEY(TARGET_VERSION_ID) REFERENCES GRAPH_VERSIONS(GRAPH_VERSION_ID), CONSTRAINT FK_GRAPH_DYNAMIC_RUN FOREIGN KEY(RUN_ID) REFERENCES GRAPH_RUNS(RUN_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_PROTOCOL_TASKS (PROTOCOL_TASK_ID VARCHAR2(256) PRIMARY KEY, PROTOCOL_VERSION VARCHAR2(32) NOT NULL, RUN_ID VARCHAR2(128) NOT NULL, PRINCIPAL_ID VARCHAR2(256) NOT NULL, STATUS VARCHAR2(32) NOT NULL, CURSOR_SEQ NUMBER(19,0) DEFAULT 0 NOT NULL, CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_PROTOCOL_RUN FOREIGN KEY(RUN_ID) REFERENCES GRAPH_RUNS(RUN_ID), CONSTRAINT UK_GRAPH_PROTOCOL_RUN UNIQUE(PROTOCOL_VERSION,RUN_ID,PRINCIPAL_ID))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE TABLE GRAPH_TELEMETRY_DELIVERIES (DELIVERY_ID VARCHAR2(128) PRIMARY KEY, OUTBOX_ID VARCHAR2(128), MAPPING_VERSION VARCHAR2(64) NOT NULL, DESTINATION_REF VARCHAR2(512) NOT NULL, STATUS VARCHAR2(32) DEFAULT ''PENDING'' NOT NULL, TRACE_ID VARCHAR2(128), SPAN_ID VARCHAR2(128), LAST_ERROR VARCHAR2(2000), CREATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, UPDATED_AT TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT FK_GRAPH_TELEMETRY_OUTBOX FOREIGN KEY(OUTBOX_ID) REFERENCES GRAPH_OUTBOX(OUTBOX_ID), CONSTRAINT UK_GRAPH_TELEMETRY_OUTBOX UNIQUE(OUTBOX_ID,DESTINATION_REF))'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IDX_GRAPH_ASSURANCE_RUN ON GRAPH_ASSURANCE_EVIDENCE(RUN_ID,CREATED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
BEGIN EXECUTE IMMEDIATE 'CREATE INDEX IDX_GRAPH_DYNAMIC_STATUS ON GRAPH_DYNAMIC_PROPOSALS(STATUS,UPDATED_AT)'; EXCEPTION WHEN OTHERS THEN IF SQLCODE <> -955 THEN RAISE; END IF; END;
/
